using LittleLeo;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "ActionGainVariableHexDieAction", menuName = "Data/Battle/Battle Actions/Tactical Actions/ActionGainVariableHexDie Action")]
public class ActionGainVariableHexDieAction : BattleAction
{
	[Header("Action Gain Variable Hex Die")]
	[SerializeField]
	private HexAction hexAction;

	[SerializeField]
	private BattleAction battleAction;

	public HexAction HexAction => hexAction;

	public BattleAction BattleAction => battleAction;

	public override void CastAmount(int amount, GameObject source)
	{
		battleAction.Cast(source);
		InvokeAlternatives.InvokeAfterMultipleFrames(ReferenceSingleton<CoroutineHandler>.Instance, 3, delegate
		{
			hexAction.CastAmount(amount, source);
		});
	}
}
